/// x86_64 Linux bundles (B-49) keep llama.cpp's shared libraries in `<resource folder>/ggml`
/// (`/usr/lib/Borealis/ggml` in the deb and rpm, `usr/lib/Borealis/ggml` in the AppImage; `src/semantic_backend.rs`),
/// so the binary's run path names that folder. Last: `ggml` next to a release binary in the cargo target folder.
const LINUX_RPATH: &str = "$ORIGIN/../lib/Borealis/ggml:$ORIGIN/../lib/borealis/ggml:$ORIGIN/ggml";

/// `cfg(ai_cli)`: the AI CLI integration (AI commands, "Import anything", the AI profile, the `--mcp` mode, the
/// drive CLI and the LAN AI host) is compiled in. Desktop builds have it; phones and the Mac App Store flavour
/// (`--features mas`, MAS1) do not, because they cannot launch or install other programs.
#[must_use]
fn has_ai_cli(target_os: &str, mas: bool) -> bool {
    !matches!(target_os, "android" | "ios") && !mas
}

/// `cfg(self_update)`: the in-app updater (#25, UP2; `self_update.rs`) is compiled in. Desktop builds have it; phones
/// (no Tauri updater; the stores or the website update them) and the Mac App Store flavour (store rules) do not. At
/// runtime it is registered only for an install that can replace itself (Windows NSIS, the macOS app, an AppImage).
#[must_use]
fn has_self_update(target_os: &str, mas: bool) -> bool {
    !matches!(target_os, "android" | "ios") && !mas
}

fn main() {
    let target_os = std::env::var("CARGO_CFG_TARGET_OS").unwrap_or_default();
    let target_arch = std::env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
    if target_os == "linux" && target_arch == "x86_64" {
        println!("cargo:rustc-link-arg-bins=-Wl,-rpath,{LINUX_RPATH}");
    }
    println!("cargo:rustc-check-cfg=cfg(ai_cli)");
    let mas = std::env::var_os("CARGO_FEATURE_MAS").is_some();
    if has_ai_cli(&target_os, mas) {
        println!("cargo:rustc-cfg=ai_cli");
    }
    println!("cargo:rustc-check-cfg=cfg(self_update)");
    if has_self_update(&target_os, mas) {
        println!("cargo:rustc-cfg=self_update");
    }
    if target_os == "windows" && std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc") {
        embed_test_manifest();
    }
    let manifest = tauri_build::AppManifest::new().commands(COMMANDS);
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(manifest))
        .expect("failed to run the Tauri build script");
}

/// Windows test executables get the same Common Controls v6 manifest the app gets from tauri-build.
///
/// tauri-build links its manifest resource into the app binary only, so an integration test that starts the
/// real Tauri runtime (`tests/app_updater.rs`) fails to load with STATUS_ENTRYPOINT_NOT_FOUND
/// (`TaskDialogIndirect` lives only in Common Controls v6). The flags apply to test targets only, so the shipped
/// app is unchanged.
fn embed_test_manifest() {
    let manifest =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("windows-test-manifest.xml");
    println!("cargo:rerun-if-changed={}", manifest.display());
    println!("cargo:rustc-link-arg-tests=/MANIFEST:EMBED");
    println!(
        "cargo:rustc-link-arg-tests=/MANIFESTINPUT:{}",
        manifest.display()
    );
}
